={{
  {
    "contents": [
      {
        "role": "user",
        "parts": [
          {
            "text": `You are building a test-prompt bank for an LLM brand visibility audit.\nBrand: ${$json.brand_name} (${$json.brand_domain})\nIndustry: ${$json.industry}\nTarget buyer: ${$json.target_market}\nCompetitors to watch for: ${$json.competitors}\n\nGenerate ${$json.prompt_count} realistic prompts that a real buyer would type into ChatGPT, Gemini, or Perplexity while researching this category. Cover this mix of intents:\n- direct brand lookup (2)\n- 'best tool for X' recommendation asks (4)\n- head-to-head comparison vs named competitors (3)\n- problem/pain-point phrased asks with no brand named (4)\n- 'alternatives to <competitor>' asks (2)\nReturn ONLY JSON matching the schema.`
          }
        ]
      }
    ],
    "generationConfig": {
      "responseMimeType": "application/json",
      "responseSchema": {
        "type": "OBJECT",
        "properties": {
          "prompts": {
            "type": "ARRAY",
            "items": {
              "type": "OBJECT",
              "properties": {
                "id": {
                  "type": "STRING"
                },
                "category": {
                  "type": "STRING"
                },
                "prompt_text": {
                  "type": "STRING"
                }
              },
              "required": [
                "id",
                "category",
                "prompt_text"
              ]
            }
          }
        },
        "required": [
          "prompts"
        ]
      }
    }
  }
}}

