return [{ json: { prompts: parsed.prompts } }];

parameters.jsonBody:
={{
  {
    "contents": [
      {
        "role": "user",
        "parts": [
          {
            "text": "You are auditing brand visibility for " + $('Set Brand Configuration').first().json.brand_name + " in LLM answers. Be strict and skeptical — do not let confident tone fool you into thinking a model actually knows the brand. Use ONLY the brand information given below; do not assume any industry, niche, or business type that isn't explicitly stated.\n\nBrand being audited: " + $('Set Brand Configuration').first().json.brand_name + "\nWhat this brand actually does (ground truth): " + ($('Set Brand Configuration').first().json.brand_description ? $('Set Brand Configuration').first().json.brand_description : 'NOT PROVIDED — be extra conservative. Only mark genuinely_recognized true if a model states specific, internally-consistent, plausible facts about the brand.') + "\nKnown real competitors: " + ($('Set Brand Configuration').first().json.competitors ? $('Set Brand Configuration').first().json.competitors : 'NOT PROVIDED') + "\nOriginal prompt asked: " + $('Limit to 10 Prompts').item.json.prompt_text + "\n\nYou are evaluating THREE answers from different AI agents. Two are UNGROUNDED (no live web access), and one is GROUNDED (used live web search):\n\n--- 1. Groq (ungrounded) ---\n" + $('Query Groq Llama Agent').first().json.output + "\n\n--- 2. OpenRouter (ungrounded) ---\n" + $('Query OpenRouter Agent').first().json.output + "\n\n--- 3. Search Agent (grounded via web search) ---\n" + $('Search Grounded Agent').first().json.output + "\n\nFor EACH of the three agents (Groq, OpenRouter, and Search Agent), evaluate the following:\n\n1. genuinely_recognized: true ONLY if the agent demonstrates real, specific, factually plausible knowledge of " + $('Set Brand Configuration').first().json.brand_name + ". If the agent says it has never heard of it, is unsure, or gives generic 'how to vet an unknown provider' advice, that is HALLUCINATED SPECULATION. In those cases, genuinely_recognized MUST be false.\n2. mentioned: true if the brand name explicitly appears anywhere in the model's text. A model can hallucinate the facts (genuinely_recognized = false) but still successfully mention the brand (mentioned = true). If the name is nowhere in the text, it is false.\n3. position: headline/body/footnote/not_mentioned — evaluate this based on where the mention occurs if mentioned is true.\n4. sentiment: -1 to 1 — evaluate the tone if mentioned is true; otherwise 0.\n5. competitors: ONLY real business competitors operating in the SAME category as " + $('Set Brand Configuration').first().json.brand_name + ". Do NOT include generic underlying tools unless recommended as a direct alternative.\n6. hallucinated_guess: true if the agent admitted uncertainty and then fabricated guesses about what the brand might be, or if it got the facts completely wrong while confidently using the brand name.\n\nFor the Search Agent specifically: extract cited source domains into search_agent_citations, and set search_agent_used_real_grounding: true if the answer reflects actual retrieved facts.\n\nFinally, compute the overall_visibility_score (0-100) by averaging the MENTIONS across ALL THREE answers:\n- Treat mentioned: false as a score of 0 for that model.\n- Treat mentioned: true as a score of 100 for that model.\n- Weight the Search Agent double.\nFormula: (Groq_Mention_Score + OpenRouter_Mention_Score + (Search_Agent_Mention_Score * 2)) / 4.\n\nReturn ONLY JSON matching the schema."
          }
        ]
      }
    ],
    "generationConfig": {
      "responseMimeType": "application/json",
      "responseSchema": {
        "type": "OBJECT",
        "properties": {
          "groq_genuinely_recognized": { "type": "BOOLEAN" },
          "groq_mentioned": { "type": "BOOLEAN" },
          "groq_position": { "type": "STRING", "enum": ["headline", "body", "footnote", "not_mentioned"] },
          "groq_sentiment": { "type": "NUMBER" },
          "groq_competitors": { "type": "ARRAY", "items": { "type": "STRING" } },
          "groq_hallucinated_guess": { "type": "BOOLEAN" },
          "openrouter_genuinely_recognized": { "type": "BOOLEAN" },
          "openrouter_mentioned": { "type": "BOOLEAN" },
          "openrouter_position": { "type": "STRING", "enum": ["headline", "body", "footnote", "not_mentioned"] },
          "openrouter_sentiment": { "type": "NUMBER" },
          "openrouter_competitors": { "type": "ARRAY", "items": { "type": "STRING" } },
          "openrouter_hallucinated_guess": { "type": "BOOLEAN" },
          "search_agent_genuinely_recognized": { "type": "BOOLEAN" },
          "search_agent_mentioned": { "type": "BOOLEAN" },
          "search_agent_position": { "type": "STRING", "enum": ["headline", "body", "footnote", "not_mentioned"] },
          "search_agent_sentiment": { "type": "NUMBER" },
          "search_agent_competitors": { "type": "ARRAY", "items": { "type": "STRING" } },
          "search_agent_citations": { "type": "ARRAY", "items": { "type": "STRING" } },
          "search_agent_used_real_grounding": { "type": "BOOLEAN" },
          "search_agent_hallucinated_guess": { "type": "BOOLEAN" },
          "overall_visibility_score": { "type": "NUMBER" }
        },
        "required": [
          "groq_genuinely_recognized",
          "groq_mentioned",
          "openrouter_genuinely_recognized",
          "openrouter_mentioned",
          "search_agent_genuinely_recognized",
          "search_agent_mentioned",
          "overall_visibility_score"
        ]
      }
    }
  }
}}

parameters.jsCode:
const raw = $input.first().json.candidates[0].content.parts[0].text;
const s = JSON.parse(raw);

return [{ 
  json: {
    run_id: $('Set Brand Configuration').first().json.run_id,

    // Changed from 'Loop Over Prompts' to 'Limit' to match your workflow
    prompt_id: $('Limit to 10 Prompts').first().json.id,
    category: $('Limit to 10 Prompts').first().json.category,
    prompt_text: $('Limit to 10 Prompts').first().json.prompt_text,

    // Groq
    groq_genuinely_recognized: s.groq_genuinely_recognized,
    groq_mentioned: s.groq_mentioned, 
    groq_position: s.groq_position,
    groq_sentiment: s.groq_sentiment, 
    groq_competitors: (s.groq_competitors || []).join(', '),
    groq_hallucinated_guess: s.groq_hallucinated_guess,

    // OpenRouter
    openrouter_genuinely_recognized: s.openrouter_genuinely_recognized,
    openrouter_mentioned: s.openrouter_mentioned, 
    openrouter_position: s.openrouter_position,
    openrouter_sentiment: s.openrouter_sentiment, 
    openrouter_competitors: (s.openrouter_competitors || []).join(', '),
    openrouter_hallucinated_guess: s.openrouter_hallucinated_guess,

    // Search Agent
    search_agent_genuinely_recognized: s.search_agent_genuinely_recognized,
    search_agent_mentioned: s.search_agent_mentioned, 
    search_agent_position: s.search_agent_position,
    search_agent_sentiment: s.search_agent_sentiment,
    search_agent_competitors: (s.search_agent_competitors || []).join(', '),
    search_agent_citations: (s.search_agent_citations || []).join(', '),
    search_agent_used_real_grounding: s.search_agent_used_real_grounding,
    search_agent_hallucinated_guess: s.search_agent_hallucinated_guess,

    // Overall
    overall_visibility_score: s.overall_visibility_score,
    timestamp: new Date().toISOString()
  } 
}];

